create sequence emdb_media.movie_sequence start with 1 increment by 1;
create sequence emdb_media.person_sequence start with 1 increment by 50;
create table emdb_media.Movies (original_language varchar(2) not null, release_date date, runtime integer, score float4 not null check ((score<=10) and (score>=0)), tmdb_id integer not null unique, budget bigint, createdAt timestamp(6) with time zone not null, id bigint not null, modifiedAt timestamp(6) with time zone not null, revenue bigint, backdrop uuid unique, poster uuid unique, status varchar(16) not null check ((status in ('CANCELED','ENDED','IN_PRODUCTION','PILOT','PLANNED','POST_PRODUCTION','RELEASED','RETURNING_SERIES','RUMORED'))), title varchar(140) not null, tagline varchar(150), overview varchar(1024), homepage varchar(2048), primary key (id), constraint uk_movies_title_release_date unique (title, release_date));
create table emdb_media.People (birth_date date, death_date date, tmdb_id integer not null unique, createdAt timestamp(6) with time zone not null, id bigint not null, modifiedAt timestamp(6) with time zone not null, gender varchar(10) not null check ((gender in ('UNKNOWN','FEMALE','MALE','NON_BINARY'))), profile uuid unique, name varchar(80) not null, birth_place varchar(120), homepage varchar(2048), biography varchar(3900), primary key (id));
